      "rank": 1,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened tests of fundamental physics with unprecedented control. This is a deep and durable advance in atomic physics.",
        "attribution": "Katori's lattice-clock proposal and realization and Ye's major experimental advances make a strong, focused case for both.",
        "maturity": "The method has been independently developed and refined across laboratories and is established as a leading clock technology.",
        "uncertainties": [
          "The boundary between the original invention and subsequent advances in clock performance deserves careful attribution."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought matter-wave coherence to precision measurement, enabling sensitive tests of gravity and fundamental physics. Its conceptual reach and experimental influence are substantial.",
        "attribution": "The proposed names represent foundational interferometer concepts and influential experimental realizations; the field's development involved a broader community.",
        "maturity": "Interferometry with atoms has been reproduced in many laboratories and supports a mature range of precision measurements.",
        "uncertainties": [
          "The discovery description spans several generations of instruments, so the decisive contributions and appropriate award scope need definition."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Jean Dalibard"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices with ultracold atoms made controlled studies of many-body quantum physics possible, including regimes difficult to access in solids. This is a powerful new way to investigate fundamental phenomena.",
        "attribution": "Bloch and Greiner established landmark experimental capabilities; Dalibard contributed foundational theory and experiments in the field.",
        "maturity": "The platform has been independently reproduced and extended to increasingly complex quantum systems.",
        "uncertainties": [
          "The candidate groups several advances and several influential contributors under one description, making the precise award boundary difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable atom arrays created a remarkably flexible route to controlled many-body dynamics and quantum simulation. The platform probes collective quantum behavior in a direct, tunable way.",
        "attribution": "Browaeys and Lukin represent experimental development of atom arrays; Zoller made influential theoretical contributions to the underlying quantum simulation program.",
        "maturity": "The platform has produced a rapidly growing body of reproducible experiments, though its longer-term scientific reach is still developing.",
        "uncertainties": [
          "The field is young, and the lasting discoveries enabled by programmability are not yet fully settled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can, in principle, survive noise and support scalable computation. The ideas have reshaped quantum physics and information science.",
        "attribution": "Shor, Steane, and Kitaev made distinct foundational contributions to codes and fault-tolerant theory.",
        "maturity": "The theory is well established and experimental error correction has advanced substantially, but fully fault-tolerant computation remains an ongoing challenge.",
        "uncertainties": [
          "The balance between recognition of a foundational principle and the still-incomplete experimental realization is a judgment call."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators revealed new phases of matter with protected boundary behavior, and the quantum anomalous Hall effect demonstrated a striking quantized transport phenomenon without an external magnetic field.",
        "attribution": "Kane and Mele made central theoretical predictions; Xue led important experimental realization of the anomalous Hall effect.",
        "maturity": "The predictions and characteristic effects have been confirmed in multiple material systems and developed into a broad research area.",
        "uncertainties": [
          "This description joins related but distinct discoveries, and the experimental realization involved important contributions beyond the listed names."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Christopher Thompson",
        "Chryssa Kouveliotou",
        "Robert C. Duncan"
      ],
      "assessment": {
        "nobel_worthiness": "The magnetar model connected extreme neutron-star magnetic fields to observed high-energy transients, revealing a remarkable class of compact objects and their physics.",
        "attribution": "Thompson and Duncan developed the theoretical picture; Kouveliotou's observations provided decisive evidence for the objects.",
        "maturity": "The magnetar interpretation is well established through years of observations across multiple events.",
        "uncertainties": [
          "The discovery and confirmation involved a wider observational community, so individual experimental credit should be reviewed."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Practical femtosecond sources enabled time-resolved studies of ultrafast processes, including the later development of attosecond science. This is a major enabling advance in experimental physics.",
        "attribution": "Moulton's titanium-sapphire laser work and Keller's and Sibbett's contributions to passive mode-locking are complementary parts of the advance.",
        "maturity": "These laser technologies have been widely reproduced and underpin decades of ultrafast experiments.",
        "uncertainties": [
          "The discovery description combines laser-medium development and mode-locking advances, which may call for a narrower formulation of the prize."
        ]
      }
    }
  ]
